from pathlib import Path

def validate_input_file(root, relative):
    try:
        if not isinstance(relative,str) or not relative or "\\" in relative or ":" in relative or any(p in ("",".","..") for p in relative.split("/")): raise ValueError("invalid path")
        base=Path(root).expanduser().resolve(strict=True)
        if not base.is_dir(): raise ValueError("invalid root")
        current=base
        for component in relative.split("/"):
            current=current/component
            if current.is_symlink(): raise ValueError("symlink")
        resolved=current.resolve(strict=True)
        resolved.relative_to(base)
        if not resolved.is_file(): raise ValueError("regular file required")
        return resolved
    except (OSError,RuntimeError,TypeError,ValueError) as error:
        raise ValueError(str(error)) from None
